// Vendor SQLite source capture only. No library mounts, API writes or PG session.
// This exact program runs as the one main reader process until a UID-bound
// receiver acknowledges its complete private files, or the phase abort clock.
const fs = require('node:fs/promises');
const {constants} = require('node:fs');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const {DatabaseSync} = require('node:sqlite');
const env=process.env;
const fields={phase_token:env.COPY_PHASE_TOKEN,job_uid:env.COPY_JOB_UID,pod_uid:env.COPY_POD_UID};
const CAPTURE_PREDICATES=new Set(["capture_consistency_refused", "capture_deadline_expired", "capture_deadline_invalid", "capture_empty_ll_inventory", "capture_fence_abort_clock", "capture_fence_backend", "capture_fence_identity", "capture_fence_node", "capture_fence_schema", "capture_fence_stale", "capture_fence_start", "capture_fence_tables", "capture_fence_time", "capture_identity_missing", "capture_kind_unknown", "capture_phase_closed", "capture_release_identity", "capture_release_unsafe", "capture_source_byte_cap", "capture_source_changed", "capture_source_changed_before_release", "capture_source_missing_or_journal", "capture_source_unsafe"]);
const CAPTURE_CODES=new Set(["ERR_ASSERTION", "absolute_deadline", "capture_guard_failed", "ENOENT", "EEXIST", "EACCES", "EPERM", "ENOSPC", "ERR_SQLITE_ERROR", "SQLITE_ERROR", "MODULE_NOT_FOUND", "ERR_MODULE_NOT_FOUND", "ERR_UNKNOWN_BUILTIN_MODULE", "ERR_DLOPEN_FAILED"]);
const CAPTURE_ERROR_CLASSES=new Set(["AssertionError", "Error", "TypeError", "RangeError", "SyntaxError"]);
function captureDiagnostic(error){
 const code=CAPTURE_CODES.has(error.code)?error.code:'other';
 const message=typeof error.message==='string'?error.message.slice(0,128).split('\n',1)[0]:'';
 const predicate=code==='ERR_ASSERTION'&&CAPTURE_PREDICATES.has(message)?message:null;
 const uid=value=>typeof value==='string'&&/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(value)?value:null;
 return {type:'capture-refused',code,predicate,error_class:CAPTURE_ERROR_CLASSES.has(error.name)?error.name:'unknown',
  kind:['ll','kavita'].includes(env.COPY_CAPTURE_KIND)?env.COPY_CAPTURE_KIND:'unknown',
  phase_token:/^[0-9a-f]{32}$/.test(fields.phase_token||'')?fields.phase_token:null,job_uid:uid(fields.job_uid),pod_uid:uid(fields.pod_uid)};
}
function invariant(){
 assert(env.COPY_CAPTURE_PHASE_READY==='1','capture_phase_closed');
 assert(/^[0-9a-f]{32}$/.test(fields.phase_token||'')&&fields.job_uid&&fields.pod_uid,'capture_identity_missing');
 assert(/^[1-9][0-9]{9}(?:\.[0-9]{1,6})?$/.test(env.COPY_CAPTURE_DEADLINE_EPOCH||''),'capture_deadline_invalid');
 const deadline=Number(env.COPY_CAPTURE_DEADLINE_EPOCH)*1000;
 assert(Number.isFinite(deadline)&&Date.now()<deadline,'capture_deadline_expired');
 return deadline;
}
async function main(){
 const deadline=invariant(),kind=env.COPY_CAPTURE_KIND;
 assert(['ll','kavita'].includes(kind),'capture_kind_unknown');
 const fence=JSON.parse(env.COPY_CAPTURE_FENCE_JSON||'{}');
 assert.deepEqual(Object.keys(fence).sort(),['claim_uid','first_service_stop_observed_at','node','pg_backend_pid','pg_fence_established_at','pg_health_at','phase_token','read_only','schema','service_fence_checked_at','share_tables'].sort(),'capture_fence_schema');
 assert(fence.schema===1&&fence.read_only===true&&fence.phase_token===fields.phase_token,'capture_fence_identity');
 assert(Number.isSafeInteger(fence.pg_backend_pid)&&fence.pg_backend_pid>0&&typeof fence.claim_uid==='string'&&fence.claim_uid,'capture_fence_backend');
 assert.deepEqual(fence.share_tables,['book_requests','books_items'],'capture_fence_tables');
 assert(typeof env.COPY_CAPTURE_NODE==='string'&&env.COPY_CAPTURE_NODE.length>0&&fence.node===env.COPY_CAPTURE_NODE,'capture_fence_node');
 for(const key of ['first_service_stop_observed_at','pg_fence_established_at','pg_health_at','service_fence_checked_at'])assert(Number.isFinite(Date.parse(fence[key]))&&Date.parse(fence[key])<=Date.now(),'capture_fence_time');
 assert(Date.now()-Date.parse(fence.pg_health_at)<=12000&&Date.now()-Date.parse(fence.service_fence_checked_at)<=65000,'capture_fence_stale');
 assert(Date.parse(fence.pg_fence_established_at)>=Date.parse(fence.first_service_stop_observed_at),'capture_fence_start');
 assert(deadline<=Date.parse(fence.first_service_stop_observed_at)+250000,'capture_fence_abort_clock');
 const timer=setTimeout(()=>{console.log(JSON.stringify(captureDiagnostic({code:'absolute_deadline',name:'Error'})));process.exit(2);},deadline-Date.now());
 const base=kind==='ll'?'/config':'/kavita/config',dbName=kind==='ll'?'lazylibrarian.db':'kavita.db';
 const names=[dbName,dbName+'-wal',dbName+'-shm',dbName+'-journal'];
 const fingerprint=async name=>{invariant();try{const s=await fs.lstat(base+'/'+name,{bigint:true});assert(s.isFile()&&!s.isSymbolicLink()&&s.nlink===1n,'capture_source_unsafe');return{name,inode:String(s.ino),device:String(s.dev),size:String(s.size),uid:String(s.uid),gid:String(s.gid),mode:String(s.mode),mtimeNs:String(s.mtimeNs),ctimeNs:String(s.ctimeNs)};}catch(e){if(e.code==='ENOENT')return null;throw e;}};
 const captureStartedAt=new Date().toISOString();
 const before=[];for(const name of names)before.push(await fingerprint(name));
 assert(before[0]&&!before[3],'capture_source_missing_or_journal');
 assert(before.reduce((n,row)=>n+(row?Number(row.size):0),0)<=512*1024*1024,'capture_source_byte_cap');
 const files=[];
 for(let i=0;i<names.length;i++)if(before[i]){invariant();const target='/tmp/'+names[i];await fs.copyFile(base+'/'+names[i],target,constants.COPYFILE_EXCL);await fs.chmod(target,0o600);const bytes=await fs.readFile(target);invariant();files.push({name:names[i],size:bytes.length,sha256:crypto.createHash('sha256').update(bytes).digest('hex')});}
 const after=[];for(const name of names)after.push(await fingerprint(name));
 assert.deepEqual(before,after,'capture_source_changed');
 const db=new DatabaseSync('/tmp/'+dbName,{readOnly:true});let inventory,llBooks,querySha256;
 try{db.exec('PRAGMA query_only=ON');assert(db.prepare('PRAGMA quick_check').all().every(row=>Object.values(row).every(value=>value==='ok')),'capture_consistency_refused');inventory=db.prepare("SELECT type,name,tbl_name,sql FROM sqlite_master ORDER BY type,name").all();
  if(kind==='ll'){const {LL_BOOKS_SQL}=await import('/sync/src/books-census/run.ts');querySha256=crypto.createHash('sha256').update(LL_BOOKS_SQL).digest('hex');llBooks=db.prepare(LL_BOOKS_SQL).all();assert(llBooks.length>0,'capture_empty_ll_inventory');}
 }finally{db.close();}
 invariant();
 const proof={schema:1,readOnlySource:true,sourceWrites:0,captureStartedAt,capturedAt:new Date().toISOString(),kind,phase_token:fields.phase_token,job_uid:fields.job_uid,pod_uid:fields.pod_uid,fence,before,after,files,sqlite_master:inventory};
 await fs.writeFile('/tmp/copy-proof.json',JSON.stringify(proof)+'\n',{mode:0o600,flag:'wx'});
 if(kind==='ll'){const row={type:'ll-books-sql-capture',readOnly:true,phase:fields.phase_token,sharedAppCapture:null,captureStartedAt,capturedAt:proof.capturedAt,sourceImage:env.COPY_CAPTURE_IMAGE,queryName:'LL_BOOKS_SQL',querySha256,llReadMethod:'node:sqlite readOnly/query_only on complete guarded DB/WAL/SHM copy from read-only PVC',sourceFingerprintBefore:before,sourceFingerprintAfter:after,llBooks,sourceWrites:0};await fs.writeFile('/tmp/ll-sql.jsonl',JSON.stringify(row)+'\n',{mode:0o600,flag:'wx'});}
 console.log(JSON.stringify({type:'stopped-sqlite-capture-ready',kind,...fields,captureStartedAt,capturedAt:proof.capturedAt,files:files.map(row=>({name:row.name,size:row.size,sha256:row.sha256}))}));
 // The receiver only reads /tmp and acknowledges these exact UIDs. The main
 // reader owns its finite lifetime; no detached sleeper or child remains.
 while(true){invariant();try{const info=await fs.lstat('/tmp/capture-released.json');assert(info.isFile()&&!info.isSymbolicLink()&&info.nlink===1&&info.size<=4096,'capture_release_unsafe');const release=JSON.parse(await fs.readFile('/tmp/capture-released.json','utf8'));assert.deepEqual(release,{schema:1,...fields},'capture_release_identity');break;}catch(e){if(e.code!=='ENOENT')throw e;}await new Promise(resolve=>setTimeout(resolve,100));}
 const final=[];for(const name of names)final.push(await fingerprint(name));assert.deepEqual(before,final,'capture_source_changed_before_release');
 clearTimeout(timer);console.log(JSON.stringify({type:'stopped-sqlite-capture-released',kind,...fields}));
}
main().catch(error=>{console.error(JSON.stringify(captureDiagnostic(error)));process.exit(2);});
